DROP TABLE IF EXISTS `item_properties_display`;
CREATE TABLE `item_properties_display` (
  `entry` int unsigned NOT NULL COMMENT 'item entry',
  `build` int unsigned NOT NULL COMMENT 'valid from this client build',
  `displayid` int unsigned NOT NULL DEFAULT 0 COMMENT 'ItemDisplayInfo id of the client',
  `inventorytype` tinyint unsigned NOT NULL DEFAULT 0 COMMENT 'inventory type of the client',
  PRIMARY KEY (`entry`, `build`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Item System';

